// Mirrors the SQL function session_charge() in supabase/migrations/0002_billing.sql.
// Change both together; the unit tests (pricing.spec.ts, pricing.golden.spec.ts) cover this file
// and the golden values were generated by session_charge itself.
//
// Rules: played time = elapsed - paused. Per hour: round up to the billing block, at least the
// minimum bill. Package: fixed price inside the package minutes; overtime in billing blocks at the
// hourly rate. The rate, block and minimum are the values snapshotted when the session started.
// Money is calculated in whole paise with integers and rounded half up, like Postgres numeric.

export interface SessionSnapshot {
  rate_per_hour: number | string;
  block_min: number;
  min_bill_min: number;
  package_minutes: number | null;
  package_price: number | string | null;
  started_at: string;
  paused_at: string | null;
  paused_seconds: number;
  ended_at: string | null;
}

const toPaise = (v: number | string): number => Math.round(Number(v) * 100);
const toMs = (iso: string): number => Date.parse(iso);
const roundHalfUp = (num: number, den: number): number => Math.floor((2 * num + den) / (2 * den));

/** Milliseconds actually played at endMs (paused time removed, never negative). */
export function playedMs(s: SessionSnapshot, endMs: number): number {
  const runningPause = s.paused_at ? endMs - toMs(s.paused_at) : 0;
  return Math.max(0, endMs - toMs(s.started_at) - s.paused_seconds * 1000 - runningPause);
}

/** The charge in paise at endMs. */
export function chargePaise(s: SessionSnapshot, endMs: number): number {
  const rate = toPaise(s.rate_per_hour);
  const blockMs = s.block_min * 60_000;
  const roundedMinutes = (ms: number): number => Math.ceil(ms / blockMs) * s.block_min;
  const played = playedMs(s, endMs);

  if (s.package_minutes !== null) {
    const price = toPaise(s.package_price ?? 0);
    const packageMs = s.package_minutes * 60_000;
    if (played <= packageMs) return price;
    return price + roundHalfUp(roundedMinutes(played - packageMs) * rate, 60);
  }

  const minutes = Math.max(roundedMinutes(played), s.min_bill_min);
  return roundHalfUp(minutes * rate, 60);
}

/** The charge in rupees at endMs. */
export function sessionCharge(s: SessionSnapshot, endMs: number): number {
  return chargePaise(s, endMs) / 100;
}

/** An ended session is frozen at ended_at; an open one runs until now. */
export function chargeEndMs(s: SessionSnapshot, nowMs: number): number {
  return s.ended_at ? toMs(s.ended_at) : nowMs;
}

/** Package time left in ms (negative = overtime), or null for a per-hour session. */
export function packageRemainingMs(s: SessionSnapshot, endMs: number): number | null {
  if (s.package_minutes === null) return null;
  return s.package_minutes * 60_000 - playedMs(s, endMs);
}

/** 3725000 -> "1:02:05" */
export function formatDuration(ms: number): string {
  const total = Math.max(0, Math.floor(Math.abs(ms) / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
}
